const keys=new Set<string>();let driveX=0,driveY=0,aimX=0,aimY=0,driveId:number|null=null,aimId:number|null=null,mouseAiming=false;let steering=0,touchFire=false,wheelId:number|null=null,lastWheelAngle=0,wheelRotation=0;
